-- Frozen copy of app/schema_postgres.sql at schema version 27 (commit 6d17642): the oldest
-- PostgreSQL schema that upgrades in place. tests/test_postgres_migrations.py builds a v27
-- database from it, runs the NNNN.sql steps alone and compares with a new database. Never edit.
-- Generated by scripts/ops/generate_postgres_schema.py from SQLite schema version 27.
-- Do not edit by hand: change the SQLite migration, then regenerate.
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS lexvault_schema_meta (
    singleton BIGINT PRIMARY KEY CHECK (singleton = 1),
    version BIGINT NOT NULL
);

-- SQLite functions that application SQL calls directly.
CREATE OR REPLACE FUNCTION datetime(value TEXT, modifier TEXT) RETURNS TEXT
    LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT to_char(CASE WHEN modifier = 'localtime' THEN localtimestamp ELSE now() AT TIME ZONE 'UTC' END,
                   'YYYY-MM-DD HH24:MI:SS')
    WHERE value = 'now'
$$;

CREATE TABLE IF NOT EXISTS cases (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title TEXT NOT NULL,
    case_no TEXT NOT NULL DEFAULT '',
    case_type TEXT NOT NULL DEFAULT '刑事',
    client_name TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL DEFAULT '阅卷中',
    description TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    lifecycle_status TEXT NOT NULL DEFAULT 'active',
    archived_at TEXT,
    archived_by TEXT,
    trashed_at TEXT,
    purge_after TEXT,
    version BIGINT NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS agent_runs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    question TEXT NOT NULL,
    route TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'running',
    retrieval_mode TEXT NOT NULL DEFAULT 'hybrid_rrf',
    final_answer TEXT NOT NULL DEFAULT '',
    citations_json TEXT NOT NULL DEFAULT '[]',
    total_ms BIGINT NOT NULL DEFAULT 0,
    runtime TEXT NOT NULL DEFAULT 'native',
    checkpoint_thread_id TEXT NOT NULL DEFAULT '',
    resume_count BIGINT NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    finished_at TEXT NOT NULL DEFAULT '',
    conversation_id BIGINT,
    context_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE IF NOT EXISTS agent_steps (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    run_id BIGINT NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,
    node_name TEXT NOT NULL,
    agent_role TEXT NOT NULL,
    status TEXT NOT NULL,
    input_json TEXT NOT NULL DEFAULT '{}',
    output_json TEXT NOT NULL DEFAULT '{}',
    latency_ms BIGINT NOT NULL DEFAULT 0,
    started_at TEXT NOT NULL,
    finished_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS audit_log (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT REFERENCES cases(id) ON DELETE CASCADE,
    action TEXT NOT NULL,
    detail TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS auth_login_limits (
    bucket TEXT PRIMARY KEY,
    attempts BIGINT NOT NULL,
    expires_at BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS auth_sessions (
    session_hash TEXT PRIMARY KEY,
    kind TEXT NOT NULL CHECK(kind IN ('token', 'oidc')),
    credential_fingerprint TEXT,
    oidc_subject TEXT,
    expires_at BIGINT NOT NULL,
    created_at TEXT NOT NULL,
    last_seen_at BIGINT NOT NULL DEFAULT 0,
    CHECK (
        (kind = 'token' AND credential_fingerprint IS NOT NULL AND oidc_subject IS NULL)
        OR (kind = 'oidc' AND credential_fingerprint IS NULL AND oidc_subject IS NOT NULL)
    )
);
CREATE TABLE IF NOT EXISTS documents (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    stored_path TEXT NOT NULL DEFAULT '',
    import_key TEXT,
    mime_type TEXT NOT NULL DEFAULT 'text/plain',
    pages BIGINT NOT NULL DEFAULT 1,
    status TEXT NOT NULL DEFAULT '已索引',
    doc_type TEXT NOT NULL DEFAULT '其他材料',
    people TEXT NOT NULL DEFAULT '',
    date_range TEXT NOT NULL DEFAULT '',
    summary TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    content_hash TEXT,
    version BIGINT NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS bank_transactions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    source_document_id BIGINT REFERENCES documents(id) ON DELETE SET NULL,
    source_document_hash TEXT NOT NULL DEFAULT '',
    source_sheet TEXT NOT NULL DEFAULT '',
    source_row_number BIGINT NOT NULL,
    source_page_start BIGINT,
    source_page_end BIGINT,
    source_ref_json TEXT NOT NULL DEFAULT '{}',
    account TEXT NOT NULL DEFAULT '',
    direction TEXT NOT NULL DEFAULT 'unknown' CHECK(direction IN ('inflow','outflow','unknown')),
    amount_minor BIGINT,
    currency TEXT NOT NULL DEFAULT 'CNY',
    amount_raw TEXT NOT NULL DEFAULT '',
    transaction_time TEXT,
    time_raw TEXT NOT NULL DEFAULT '',
    counterparty TEXT NOT NULL DEFAULT '',
    memo TEXT NOT NULL DEFAULT '',
    raw_row_json TEXT NOT NULL DEFAULT '{}',
    parse_status TEXT NOT NULL DEFAULT 'parsed' CHECK(parse_status IN ('parsed','needs_review')),
    parse_warnings_json TEXT NOT NULL DEFAULT '[]',
    parser_version TEXT NOT NULL,
    row_fingerprint TEXT NOT NULL,
    created_at TEXT NOT NULL,
    UNIQUE(source_document_id, source_sheet, source_row_number, row_fingerprint)
);
CREATE TABLE IF NOT EXISTS evidence (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    category TEXT NOT NULL DEFAULT '书证',
    fact TEXT NOT NULL DEFAULT '',
    credibility TEXT NOT NULL DEFAULT '待核验',
    source_document_id BIGINT REFERENCES documents(id) ON DELETE SET NULL,
    source_page_start BIGINT NOT NULL DEFAULT 1,
    source_page_end BIGINT NOT NULL DEFAULT 1,
    quote TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL DEFAULT '待复核',
    created_at TEXT NOT NULL,
    approved_by TEXT,
    approved_at TEXT,
    version BIGINT NOT NULL DEFAULT 1,
    updated_at TEXT
);
CREATE TABLE IF NOT EXISTS bank_transaction_relations (
    transaction_id BIGINT NOT NULL REFERENCES bank_transactions(id) ON DELETE CASCADE,
    evidence_id BIGINT NOT NULL REFERENCES evidence(id) ON DELETE CASCADE,
    relation_type TEXT NOT NULL DEFAULT '资金链路',
    note TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    PRIMARY KEY(transaction_id, evidence_id, relation_type)
);
CREATE TABLE IF NOT EXISTS batch_imports (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    total_files BIGINT NOT NULL,
    processed_files BIGINT NOT NULL DEFAULT 0,
    successful_files BIGINT NOT NULL DEFAULT 0,
    failed_files BIGINT NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'queued',
    error_log_json TEXT NOT NULL DEFAULT '[]',
    created_at TEXT NOT NULL,
    started_at TEXT,
    finished_at TEXT
);
CREATE TABLE IF NOT EXISTS batch_dispatch (
    batch_id BIGINT PRIMARY KEY REFERENCES batch_imports(id) ON DELETE CASCADE,
    case_id BIGINT NOT NULL,
    state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','discharged')),
    attempts BIGINT NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS batch_import_files (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    batch_id BIGINT NOT NULL REFERENCES batch_imports(id) ON DELETE CASCADE,
    file_key TEXT NOT NULL,
    filename TEXT NOT NULL,
    stored_path TEXT NOT NULL,
    mime_type TEXT NOT NULL DEFAULT 'application/octet-stream',
    status TEXT NOT NULL DEFAULT 'pending',
    document_id BIGINT REFERENCES documents(id) ON DELETE SET NULL,
    error TEXT NOT NULL DEFAULT '',
    updated_at TEXT NOT NULL,
    UNIQUE(batch_id, file_key)
);
CREATE TABLE IF NOT EXISTS members (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    is_admin BIGINT NOT NULL DEFAULT 0 CHECK (is_admin IN (0,1)),
    permissions_json TEXT NOT NULL DEFAULT '[]',
    active BIGINT NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
    created_by TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS case_members (
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    member_id BIGINT NOT NULL REFERENCES members(id) ON DELETE CASCADE,
    role TEXT NOT NULL CHECK (role IN ('owner','reviewer','assistant','viewer')),
    created_by TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    PRIMARY KEY (case_id, member_id)
);
CREATE TABLE IF NOT EXISTS export_templates (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    description TEXT NOT NULL DEFAULT '',
    blocks_json TEXT NOT NULL,
    builtin BIGINT NOT NULL DEFAULT 0 CHECK (builtin IN (0, 1)),
    created_by TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS case_reports (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    version BIGINT NOT NULL,
    title TEXT NOT NULL,
    template_id BIGINT REFERENCES export_templates(id) ON DELETE SET NULL,
    status TEXT NOT NULL DEFAULT '草稿'
        CHECK (status IN ('草稿','待复核','已退回','已批准','已作废')),
    basis_json TEXT NOT NULL DEFAULT '{}',
    basis_hash TEXT NOT NULL DEFAULT '',
    prepared_by TEXT NOT NULL DEFAULT '',
    reviewed_by TEXT,
    approved_by TEXT,
    return_reason TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    submitted_at TEXT,
    approved_at TEXT,
    voided_at TEXT,
    superseded_by BIGINT REFERENCES case_reports(id) ON DELETE SET NULL,
    row_version BIGINT NOT NULL DEFAULT 1,
    frozen_version_id BIGINT,
    approved_version_id BIGINT,
    content_hash TEXT NOT NULL DEFAULT '',
    source_hash TEXT NOT NULL DEFAULT '',
    UNIQUE (case_id, version)
);
CREATE TABLE IF NOT EXISTS case_report_events (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    report_id BIGINT NOT NULL REFERENCES case_reports(id) ON DELETE CASCADE,
    from_status TEXT NOT NULL DEFAULT '',
    to_status TEXT NOT NULL DEFAULT '',
    action TEXT NOT NULL,
    actor TEXT NOT NULL,
    note TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS case_report_versions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    report_id BIGINT NOT NULL REFERENCES case_reports(id) ON DELETE CASCADE,
    seq BIGINT NOT NULL,
    report_version BIGINT NOT NULL,
    template_id BIGINT,
    renderer_version TEXT NOT NULL,
    source_json TEXT NOT NULL,
    source_hash TEXT NOT NULL,
    content_json TEXT NOT NULL,
    content_hash TEXT NOT NULL,
    artifact_dir TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'frozen' CHECK (status IN ('frozen','failed')),
    frozen_by TEXT NOT NULL DEFAULT '',
    frozen_at TEXT NOT NULL,
    UNIQUE (report_id, seq)
);
CREATE TABLE IF NOT EXISTS case_walls (
    case_id BIGINT PRIMARY KEY REFERENCES cases(id) ON DELETE CASCADE,
    reason TEXT NOT NULL,
    created_by TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS case_wall_grants (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES case_walls(case_id) ON DELETE CASCADE,
    principal_name TEXT NOT NULL,
    reason TEXT NOT NULL,
    granted_at TEXT NOT NULL,
    expires_at BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS case_wall_insiders (
    case_id BIGINT NOT NULL REFERENCES case_walls(case_id) ON DELETE CASCADE,
    principal_name TEXT NOT NULL,
    added_by TEXT NOT NULL,
    added_at TEXT NOT NULL,
    PRIMARY KEY (case_id, principal_name)
);
CREATE TABLE IF NOT EXISTS conversations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    user_name TEXT NOT NULL DEFAULT '本机律师',
    title TEXT NOT NULL DEFAULT '新会话',
    created_at TEXT NOT NULL,
    archived_at TEXT,
    archive_expires_at BIGINT,
    archived_by TEXT
);
CREATE TABLE IF NOT EXISTS messages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    conversation_id BIGINT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
    role TEXT NOT NULL,
    content TEXT NOT NULL,
    citations_json TEXT NOT NULL DEFAULT '[]',
    route TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    provenance_json TEXT NOT NULL DEFAULT '{}',
    kind TEXT NOT NULL DEFAULT 'answer',
    source_run_id BIGINT
);
CREATE TABLE IF NOT EXISTS chat_requests (
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    request_id TEXT NOT NULL,
    conversation_id BIGINT REFERENCES conversations(id) ON DELETE SET NULL,
    status TEXT NOT NULL CHECK(status IN ('in_progress','committed','failed','cancelled')),
    result_json TEXT,
    message_id BIGINT REFERENCES messages(id) ON DELETE SET NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    PRIMARY KEY(case_id, request_id)
);
CREATE TABLE IF NOT EXISTS pages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    document_id BIGINT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    page_no BIGINT NOT NULL,
    text TEXT NOT NULL DEFAULT '',
    summary TEXT NOT NULL DEFAULT '',
    UNIQUE(document_id, page_no)
);
CREATE TABLE IF NOT EXISTS embedding_cache (
    page_id BIGINT PRIMARY KEY REFERENCES pages(id) ON DELETE CASCADE,
    model TEXT NOT NULL,
    dimensions BIGINT NOT NULL,
    content_hash TEXT NOT NULL,
    vector_json TEXT NOT NULL,
    backend TEXT NOT NULL DEFAULT 'local',
    updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS evidence_annotations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    evidence_id BIGINT NOT NULL REFERENCES evidence(id) ON DELETE CASCADE,
    user_name TEXT NOT NULL,
    annotation_type TEXT NOT NULL,
    content TEXT NOT NULL,
    quote_start BIGINT,
    quote_end BIGINT,
    status TEXT NOT NULL DEFAULT '待处理',
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS evidence_relations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    from_evidence_id BIGINT NOT NULL REFERENCES evidence(id) ON DELETE CASCADE,
    to_evidence_id BIGINT NOT NULL REFERENCES evidence(id) ON DELETE CASCADE,
    relation_type TEXT NOT NULL DEFAULT '相互印证',
    note TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS gap_detections (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    run_id BIGINT REFERENCES agent_runs(id) ON DELETE SET NULL,
    gap_type TEXT NOT NULL,
    severity TEXT NOT NULL,
    description TEXT NOT NULL,
    suggestion TEXT NOT NULL,
    affected_evidence_ids TEXT NOT NULL DEFAULT '[]',
    status TEXT NOT NULL DEFAULT '待核验',
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS runtime_requests (
    request_id TEXT PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    runtime TEXT NOT NULL,
    protocol_version BIGINT NOT NULL,
    run_id BIGINT REFERENCES agent_runs(id) ON DELETE SET NULL,
    job_id TEXT,
    created_at TEXT NOT NULL,
    request_digest TEXT NOT NULL DEFAULT '',
    principal_name TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS host_runtime_links (
    request_id TEXT PRIMARY KEY REFERENCES runtime_requests(request_id) ON DELETE CASCADE,
    framework_run_id TEXT NOT NULL UNIQUE,
    conversation_id BIGINT REFERENCES conversations(id) ON DELETE SET NULL,
    source_version TEXT NOT NULL,
    graph_json TEXT NOT NULL,
    binding_json TEXT NOT NULL,
    deadline DOUBLE PRECISION NOT NULL,
    start_authorized BIGINT NOT NULL DEFAULT 0 CHECK(start_authorized IN (0,1)),
    status TEXT NOT NULL DEFAULT 'queued',
    cancel_requested BIGINT NOT NULL DEFAULT 0 CHECK(cancel_requested IN (0,1)),
    cursor BIGINT NOT NULL DEFAULT 0,
    result_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE IF NOT EXISTS host_backend_calls (
    request_id TEXT NOT NULL REFERENCES host_runtime_links(request_id) ON DELETE CASCADE,
    call_id TEXT NOT NULL,
    kind TEXT NOT NULL,
    request_digest TEXT NOT NULL,
    model_identity TEXT NOT NULL,
    input_chars BIGINT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('dispatched','unknown','response_known_usage_unknown','completed')),
    response_json TEXT,
    response_digest TEXT,
    input_tokens BIGINT,
    output_tokens BIGINT,
    created_at TEXT NOT NULL,
    PRIMARY KEY(request_id,call_id)
);
CREATE TABLE IF NOT EXISTS host_integration_config (
    singleton BIGINT PRIMARY KEY CHECK(singleton=1),
    profile TEXT NOT NULL CHECK(profile='synthetic-isolated-v1')
);
CREATE TABLE IF NOT EXISTS host_runtime_cleanup (
    framework_run_id TEXT PRIMARY KEY,
    request_id TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS host_runtime_events (
    request_id TEXT NOT NULL REFERENCES host_runtime_links(request_id) ON DELETE CASCADE,
    seq BIGINT NOT NULL CHECK(seq > 0),
    event_id TEXT NOT NULL,
    payload_json TEXT NOT NULL,
    PRIMARY KEY(request_id, seq),
    UNIQUE(request_id, event_id)
);
CREATE TABLE IF NOT EXISTS host_write_receipts (
    receipt_id TEXT PRIMARY KEY,
    action TEXT NOT NULL,
    idempotency_key TEXT NOT NULL,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    principal_key TEXT NOT NULL,
    source_version TEXT NOT NULL,
    request_digest TEXT NOT NULL,
    result_json TEXT NOT NULL,
    created_at TEXT NOT NULL,
    UNIQUE(action, idempotency_key)
);
CREATE TABLE IF NOT EXISTS knowledge (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title TEXT NOT NULL,
    category TEXT NOT NULL,
    text TEXT NOT NULL,
    source TEXT NOT NULL DEFAULT '内置知识库'
);
CREATE TABLE IF NOT EXISTS llm_calls (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    run_id BIGINT REFERENCES agent_runs(id) ON DELETE SET NULL,
    conversation_id BIGINT REFERENCES conversations(id) ON DELETE SET NULL,
    kind TEXT NOT NULL,
    model TEXT NOT NULL DEFAULT '',
    input_tokens BIGINT,
    output_tokens BIGINT,
    ttft_ms BIGINT,
    latency_ms BIGINT NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'ok' CHECK(status IN ('ok','failed')),
    created_at TEXT NOT NULL,
    pricing_json TEXT,
    turn_key TEXT
);
CREATE TABLE IF NOT EXISTS member_tokens (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    member_id BIGINT NOT NULL REFERENCES members(id) ON DELETE CASCADE,
    token_hash TEXT NOT NULL UNIQUE,
    label TEXT NOT NULL DEFAULT '',
    created_by TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    revoked_at TEXT
);
CREATE TABLE IF NOT EXISTS memories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    user_name TEXT NOT NULL DEFAULT '本机律师',
    kind TEXT NOT NULL DEFAULT 'agent_conclusion',
    content TEXT NOT NULL,
    vector_json TEXT NOT NULL DEFAULT '[]',
    embedding_model TEXT NOT NULL DEFAULT '',
    importance DOUBLE PRECISION NOT NULL DEFAULT 0.5,
    source_run_id BIGINT REFERENCES agent_runs(id) ON DELETE SET NULL,
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS oidc_flows (
    state_hash TEXT PRIMARY KEY,
    browser_hash TEXT NOT NULL,
    nonce TEXT NOT NULL,
    verifier TEXT NOT NULL,
    redirect_uri TEXT NOT NULL,
    settings_hash TEXT NOT NULL,
    expires_at BIGINT NOT NULL,
    previous_session_hash TEXT NOT NULL DEFAULT '',
    limit_bucket TEXT NOT NULL DEFAULT '',
    limit_expires_at BIGINT NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS page_child_index_state (
    page_id BIGINT PRIMARY KEY REFERENCES pages(id) ON DELETE CASCADE,
    page_hash TEXT NOT NULL,
    chunk_version TEXT NOT NULL,
    model_identity TEXT NOT NULL,
    backend TEXT NOT NULL,
    dimensions BIGINT NOT NULL CHECK(dimensions > 0),
    child_count BIGINT NOT NULL CHECK(child_count >= 0),
    updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS page_child_chunks (
    page_id BIGINT NOT NULL REFERENCES page_child_index_state(page_id) ON DELETE CASCADE,
    ordinal BIGINT NOT NULL CHECK(ordinal >= 0),
    char_start BIGINT NOT NULL CHECK(char_start >= 0),
    char_end BIGINT NOT NULL CHECK(char_end > char_start),
    text TEXT NOT NULL,
    vector_json TEXT NOT NULL,
    PRIMARY KEY(page_id, ordinal)
);
CREATE TABLE IF NOT EXISTS rag_evaluations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    query TEXT NOT NULL,
    expected_json TEXT NOT NULL,
    returned_json TEXT NOT NULL,
    recall_at_k DOUBLE PRECISION NOT NULL,
    mrr DOUBLE PRECISION NOT NULL,
    citation_coverage DOUBLE PRECISION NOT NULL,
    latency_ms BIGINT NOT NULL,
    evaluation_id TEXT NOT NULL DEFAULT '',
    dataset_name TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS review_jobs (
    id TEXT PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    principal TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'queued',
    request_json TEXT NOT NULL,
    result_json TEXT NOT NULL DEFAULT '{}',
    error_json TEXT NOT NULL DEFAULT '{}',
    run_id BIGINT REFERENCES agent_runs(id) ON DELETE SET NULL,
    created_at TEXT NOT NULL,
    finished_at TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS review_tasks (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id BIGINT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    kind TEXT NOT NULL DEFAULT '阅卷',
    title TEXT NOT NULL,
    detail TEXT NOT NULL DEFAULT '',
    assignee_member_id BIGINT REFERENCES members(id) ON DELETE SET NULL,
    assignee_name TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL DEFAULT '待处理'
        CHECK (status IN ('待处理','进行中','待复核','已完成','已取消')),
    due_at TEXT,
    evidence_id BIGINT REFERENCES evidence(id) ON DELETE SET NULL,
    created_by TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    closed_at TEXT,
    version BIGINT NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS review_task_events (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id BIGINT NOT NULL REFERENCES review_tasks(id) ON DELETE CASCADE,
    from_status TEXT NOT NULL DEFAULT '',
    to_status TEXT NOT NULL DEFAULT '',
    action TEXT NOT NULL DEFAULT '',
    actor TEXT NOT NULL,
    note TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS security_events (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_type TEXT NOT NULL,
    outcome TEXT NOT NULL,
    actor TEXT,
    case_id BIGINT,
    detail TEXT NOT NULL DEFAULT '',
    request_path TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_agent_runs_case ON agent_runs(case_id, id DESC);
CREATE INDEX IF NOT EXISTS idx_agent_steps_run ON agent_steps(run_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_agent_steps_run_node ON agent_steps(run_id, node_name);
CREATE INDEX IF NOT EXISTS idx_annotations_evidence ON evidence_annotations(evidence_id);
CREATE INDEX IF NOT EXISTS idx_auth_login_limits_expiry ON auth_login_limits(expires_at);
CREATE INDEX IF NOT EXISTS idx_auth_sessions_expires ON auth_sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_bank_transactions_case_account ON bank_transactions(case_id, account);
CREATE INDEX IF NOT EXISTS idx_bank_transactions_case_counterparty ON bank_transactions(case_id, counterparty);
CREATE INDEX IF NOT EXISTS idx_bank_transactions_case_time ON bank_transactions(case_id, transaction_time);
CREATE INDEX IF NOT EXISTS idx_batch_dispatch_pending ON batch_dispatch(state, batch_id);
CREATE INDEX IF NOT EXISTS idx_batch_imports_case ON batch_imports(case_id, id DESC);
CREATE INDEX IF NOT EXISTS idx_case_members_member ON case_members(member_id);
CREATE INDEX IF NOT EXISTS idx_case_report_events_report ON case_report_events(report_id, id);
CREATE INDEX IF NOT EXISTS idx_case_report_versions_report ON case_report_versions(report_id, seq);
CREATE INDEX IF NOT EXISTS idx_case_reports_case ON case_reports(case_id, status);
CREATE INDEX IF NOT EXISTS idx_case_wall_grants_lookup ON case_wall_grants(case_id, principal_name, expires_at);
CREATE INDEX IF NOT EXISTS idx_cases_lifecycle ON cases(lifecycle_status, purge_after);
CREATE INDEX IF NOT EXISTS idx_chat_requests_status ON chat_requests(status, updated_at);
CREATE INDEX IF NOT EXISTS idx_chat_requests_updated ON chat_requests(updated_at);
CREATE INDEX IF NOT EXISTS idx_conversations_archive_expiry ON conversations(archive_expires_at);
